R=Path(__file__).parent;a=json.loads((R/'independent-verification.json').read_text());assert a['fullPolynomialIdentityVerified'] and not a['sharpnessClaimed'];assert a['certificateSha256']==hashlib.sha256((R/'sos-certificate.json').read_bytes()).hexdigest();b=F(a['bound']);B=r'\frac{'+str(b.numerator)+'}{'+str(b.denominator)+'}'
